x_comment('x_ReasoningWithTense-InferenceMt-SingleDateSeries',"This #$Microtheory contains rules about relations between\ninstances of\n#$ReasoningWithTenseMicrotheory-SingleDateSeries, which\nrepresent dates of a single #$CalendarCoveringType.  At the present\n(Jan/2000), the notions involved in such rules are\n#$reasoningWithTenseMtTime, #$reasoningWithTenseMtDate and\n#$mtPrecedes-Metric etc.  Note that rules in this microtheory amounts to\nsemantic interpretations of formulas in microtheories that are\ninstances of\n#$ReasoningWithTenseMicrotheory-SingleDateSeries, and thus\nshould not be present in those microtheories.") :- x_cid(a65b1276f1c6c3).
xc_microtheory(a65b1276f1c6c3,'x_ReasoningWithTense-InferenceMt-SingleDateSeries').
xc_source_file(a65b1276f1c6c3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ReasoningWithTense-InferenceMt-SingleDateSeries.krf').
